"MaxAgeParameters": {

"FollowOrigin": "off",

"CacheTime": 604800

}

}

]

},

{

"Condition": "${http.request.file_extension} in ['css', 'js']",

"Actions": [

{

"Name": "Cache",

"CacheParameters": {

"CustomTime": {

"Switch": "on",

"IgnoreCacheControl": "off",

