"CustomTime": {

"Switch": "on",

"IgnoreCacheControl": "off",

"CacheTime": 600

}

}

},

{

"Name": "MaxAge",

"MaxAgeParameters": {

"FollowOrigin": "off",

"CacheTime": 0

}

}

]

},

{

"Condition": "${http.request.uri.path} matches '^/(category|tag|page|author)/'",

"Actions": [

{

"Name": "Cache",

