"CustomTime": {

"Switch": "on",

"IgnoreCacheControl": "off",

"CacheTime": 600

}

}

},

{

"Name": "MaxAge",

"MaxAgeParameters": {

"FollowOrigin": "off",

"CacheTime": 0

}

}

]

},

{

"Condition": "${http.request.file_extension} in ['html', 'htm']",

"Actions": [

{

"Name": "Cache",

"CacheParameters": {

"CustomTime": {

"Switch": "on",

"IgnoreCacheControl": "off",

"CacheTime": 300

}

}

},

{

"Name": "MaxAge",

"MaxAgeParameters": {

"FollowOrigin": "off",

"CacheTime": 0

}

}

]

}

],

"Description": []

},

{

"Branches": [

{

"Condition": "${http.request.uri.path} matches '^/(wp-admin(/|$)|wp-json(/|$)|wp-login[.]php$|xmlrpc[.]php$|wp-cron[.]php$|wp-comments-post[.]php$)'",

